// Go caller for examples/deepinfer/flops_pairs.om. Every Omega declaration comes from the omeganative
// package (omega_native.go, generated by tools/native); this file has no cgo of its own. Expected values:
// evidence/deepinfer-flops-pairs/wolfram.md.
package main

import (
	"fmt"
	"os"

	on "omegacaller/omeganative"
)

var fails int

func check(name string, ok bool) {
	if ok {
		fmt.Println("PASS", name)
	} else {
		fmt.Println("FAIL", name)
		fails++
	}
}

type v struct {
	f      string
	a      []int64
	status uint32
	want   int64
}

func call(x v, r *uint64) uint32 {
	u := make([]uint64, len(x.a))
	for i, a := range x.a {
		u[i] = uint64(a)
	}
	switch x.f {
	case "floor_prefix":
		return on.Omega2_floor_prefix(r, u[0], u[1])
	case "capped_prefix":
		return on.Omega2_capped_prefix(r, u[0], u[1], u[2])
	}
	return on.Omega2_pairs(r, u[0], u[1], u[2], u[3])
}

func main() {
	vs := []v{
		{"floor_prefix", []int64{9, 2}, 0, 20},
		{"capped_prefix", []int64{9, 2, 3}, 0, 18},
		{"pairs", []int64{3, 9, 2, 3}, 0, 16},
		{"pairs", []int64{3, 9, 2, 0}, 0, 18},
		{"pairs", []int64{0, 4096, 1, 512}, 0, 1966336},
		{"floor_prefix", []int64{3037000499, 1}, 0, 4611686016981624750},
		{"capped_prefix", []int64{4611686018427387904, 1, 2}, 0, 9223372036854775807},
		{"floor_prefix", []int64{3037000500, 1}, 1, 0},
		{"capped_prefix", []int64{4611686018427387905, 1, 2}, 1, 0},
		{"capped_prefix", []int64{0, 4294967296, 2147483648}, 1, 0},
		{"floor_prefix", []int64{-1, 1}, 9, 0},
		{"floor_prefix", []int64{5, 0}, 9, 0},
		{"pairs", []int64{5, 3, 1, 0}, 9, 0},
		{"pairs", []int64{0, 3, 1, -1}, 9, 0},
	}
	const sentinel = uint64(0x5a5a5a5a5a5a5a5a)
	check("ident: library == binding", on.Omega2_ident_flops_pairs() == on.Omega2Ident_flops_pairs)
	for _, x := range vs {
		r := sentinel
		st := call(x, &r)
		ok := st == x.status
		if st == on.OmegaOK {
			ok = ok && int64(r) == x.want
		} else {
			ok = ok && r == sentinel
		}
		check(fmt.Sprintf("%s %v -> status %d", x.f, x.a, st), ok)
	}
	check("null result refused 32", on.Omega2_pairs(nil, 0, 3, 1, 0) == on.OmegaBadArg)
	if fails != 0 {
		os.Exit(1)
	}
}
